<script setup>
import {onBeforeUnmount,ref,watch} from 'vue';
import {MoreHorizontal} from '@lucide/vue';
import {notificationIcon,notificationColor} from './notificationPresentation.js';
const props=defineProps({item:Object,unread:Boolean,agencyName:String,agencyLogo:String,preferences:Object,disabled:Boolean});
const emit=defineEmits(['open','options','action','snooze']);const offset=ref(0),held=ref(false),holdChoice=ref(null),logoFailed=ref(false);let drag,timer,suppress=0;
watch(()=>props.agencyLogo,()=>logoFailed.value=false);
const action=()=>{const value=offset.value<0?props.preferences?.swipeLeft || 'archive':props.preferences?.swipeRight || 'read';return value==='archive'?(props.item.dismissed_at?'restore':'delete'):value;};
const label=()=>({delete:'Delete',restore:'Restore',read:'Read',unread:'Unread',none:''}[action()] || '');
function cancel(){clearTimeout(timer);drag=null;offset.value=0;held.value=false;holdChoice.value=null;}
function options(){if(props.disabled || Date.now()<suppress)return;suppress=Date.now()+700;cancel();emit('options',props.item);}
function hold(){if(!drag || props.disabled)return;held.value=true;offset.value=0;try{drag.node.setPointerCapture?.(drag.id);}catch{}}
function start(e){if(props.disabled || e.button && e.pointerType==='mouse')return;cancel();drag={x:e.clientX,y:e.clientY,node:e.currentTarget,id:e.pointerId};timer=setTimeout(hold,500);}
function move(e){if(!drag)return;const x=e.clientX-drag.x,y=e.clientY-drag.y;if(held.value){holdChoice.value=x < -24?'hour':x > 24?'tomorrow':null;return;}if(Math.abs(x)>8||Math.abs(y)>8)clearTimeout(timer);if(Math.abs(y)>Math.abs(x)&&Math.abs(y)>12){cancel();return;}if(Math.abs(x)>12){try{drag.node.setPointerCapture?.(drag.id);}catch{}offset.value=Math.max(-100,Math.min(100,x));}}
function finish(){clearTimeout(timer);if(held.value){const choice=holdChoice.value;cancel();suppress=Date.now()+700;emit('snooze',props.item,choice);return;}const act=action(),swiped=Math.abs(offset.value)>=65;cancel();if(swiped){suppress=Date.now()+700;if(act!=='none')emit('action',props.item,act);}}
function preventHeldScroll(event){if(held.value && event.cancelable)event.preventDefault();}
function contextSnooze(){if(held.value || props.disabled || Date.now()<suppress)return;cancel();suppress=Date.now()+700;emit('snooze',props.item,null);}
function open(){if(Date.now()<suppress || props.disabled)return;emit('open',props.item);}
onBeforeUnmount(cancel);
</script>
<template>
 <article class="notification-row" :class="{unread,swiping:offset!==0,holding:held}"><div class="reveal" :class="[action(),{right:offset<0}]">{{ label() }}</div><button type="button" class="notification-card" :disabled="disabled" :style="{transform:`translateX(${offset}px)`}" @pointerdown="start" @pointermove="move" @pointerup="finish" @pointercancel="cancel" @touchmove="preventHeldScroll" @click="open" @contextmenu.prevent="contextSnooze"><span class="notification-identity"><span class="type-icon" :style="{color:notificationColor(item)}" :title="item.catalog?.label"><component :is="notificationIcon(item)" :size="20" aria-hidden="true"/></span><img v-if="agencyLogo&&!logoFailed" class="agency-icon" :src="agencyLogo" :alt="agencyName || 'Agency'" @error="logoFailed=true"/></span><span class="copy"><strong>{{item.title}}</strong><span v-if="item.client_display_name && !item.title?.includes(item.client_display_name)" class="client-label">{{item.client_display_name}}</span><span class="preview">{{item.message}}</span><small>{{agencyName}}<template v-if="agencyName"> · </template>{{new Date(item.created_at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}}</small></span><span v-if="unread" class="unread-dot" aria-label="Unread"/></button><button class="options" type="button" :disabled="disabled" :aria-label="`Options for ${item.title}`" @click="options"><MoreHorizontal :size="20"/></button><div v-if="held" class="hold-snooze" aria-live="polite"><span :class="{selected:holdChoice==='hour'}">← Snooze 1 hour</span><span :class="{selected:holdChoice==='tomorrow'}">Tomorrow 9 AM →</span><small>Slide and release, or release here for options</small></div></article>
</template>
<style scoped>
.notification-row{position:relative;overflow:hidden;border-bottom:1px solid #e0e7f2;background:white}.notification-card{position:relative;z-index:1;display:flex;align-items:flex-start;gap:10px;width:100%;box-sizing:border-box;padding:14px 42px 14px 13px;text-align:left;border:0;background:white;color:#203b5b;font:inherit;touch-action:pan-y;user-select:none;-webkit-touch-callout:none}.notification-identity{display:flex;align-items:center;flex-direction:column;gap:5px;flex-shrink:0;width:30px}.type-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:#e8eef8}.agency-icon{width:19px;height:19px;object-fit:contain}.copy{display:flex;flex-direction:column;gap:5px;min-width:0;flex:1}.copy strong{font-size:13px;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.client-label{font-size:11px;font-weight:650;color:#3b5c83}.preview{font-size:12px;line-height:1.45;color:#536b87;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.copy small{font-size:10px;color:#6e8097}.unread .notification-card{background:#f0f5ff}.unread-dot{width:6px;height:6px;border-radius:50%;background:#2d60d7;flex-shrink:0;margin-top:6px}.options{position:absolute;top:6px;right:0;z-index:2;display:grid;place-items:center;width:40px;min-height:42px;border:0;background:transparent;color:#637f9f}.reveal{position:absolute;inset:0;display:flex;align-items:center;padding:12px;background:#e4efff;color:#315da8;visibility:hidden;font:600 12px system-ui}.swiping .reveal{visibility:visible}.reveal.right{justify-content:flex-end}.reveal.delete,.reveal.restore{background:#f9e7e7;color:#9c3c43}.hold-snooze{position:absolute;inset:0;z-index:4;background:#e9f1fdf2;display:flex;align-items:center;justify-content:space-around;gap:4px;padding:10px 8px 25px;pointer-events:none;color:#284e80;font:600 11px system-ui}.hold-snooze span{border-radius:8px;padding:9px}.hold-snooze .selected{background:#245be0;color:white}.hold-snooze small{position:absolute;bottom:7px;font-size:9px;font-weight:400}.holding .options{visibility:hidden}button:focus-visible{outline:3px solid #7ba5f0;outline-offset:-3px}
</style>
